using System.IO;
namespace MRS;
internal sealed record SiteChannelData(string Protocol,string[] Folders,string Scope,long Hz,string Channel,string Role,string Identifiers,long? Uplink=null,string Evidence="Observed",DateTimeOffset? Seen=null)
{
 internal string Key=>Scope+":"+Hz;
 internal static SiteChannelData? FromP25(P25Discovery d){var p=d.Observation;if(p.Replay||!p.IsValidated||d.Category=="Band plan"||d.FrequencyHz is not long hz||p.P25Identity is not {} id)return null;var target=p.P25SiteAnnouncement;int? sys=target?.SystemId??id.SystemId;int? rfss=target?.RfssId??id.RfssId,site=target?.SiteId??id.SiteId;int? wacn=target?.SystemId is int other&&other!=id.SystemId?null:id.Wacn;bool full=wacn.HasValue&&sys.HasValue&&rfss.HasValue&&site.HasValue;string system=full?$"{wacn:X5}-{sys:X3}":$"Provisional system {sys:X3} via NAC {id.Nac:X3} at {p.FrequencyHz/1e6:F6}";string siteName=site.HasValue?$"RFSS {rfss} - Site {site}":"Unresolved site";string scope=$"P25:{system}:{rfss}:{site}";var channel=target?.Channels.FirstOrDefault(c=>c.Channel.DownlinkHz==hz)?.Channel??p.P25Assignments?.FirstOrDefault(a=>a.Channel.DownlinkHz==hz)?.Channel??p.P25Channel;string ch=channel==null?"":$"{channel.Identifier:00}-{channel.ChannelNumber:0000}";string identity=$"WACN {wacn:X5}; System {sys:X3}; RFSS {rfss}; Site {site}"+(target==null?$"; NAC {id.Nac:X3}":"; target NAC not supplied; advertised target");return new("P25",["P25",system,siteName],scope,hz,ch,d.Category,identity,channel?.UplinkHz,full?(target==null?"Observed":"Advertised; not directly monitored"):"Provisional identity",d.LastSeen);}
 internal static SiteChannelData? FromDmr(DmrReception r){if(r.Context.Replay||r.Context.FrequencyHz is not long hz||DiscoveryVisibility.Unverified(r.Fields))return null;var f=r.Fields;bool full=f.Network.HasValue&&f.Site.HasValue;string variant=f.SystemType=="DMR (type unknown)"?f.Protocol:f.SystemType;string network=f.Network is int n?$"Network {n}":$"Unassigned at {hz/1e6:F6}";string site=f.Site is int s?$"Site {s}":"Unresolved site";return new(f.Protocol,[f.Protocol,variant,network,site],$"{f.Protocol}:{variant}:{network}:{site}",hz,"","Observed carrier",$"{variant}; Network {f.Network}; Site {f.Site}"+(f.Protocol=="DMR"?$"; CC {f.ColorCode}":$"; Area {f.Area}; Home {f.Home}"),null,full?"Observed":"Provisional identity",r.Seen);}
 internal FrequencyItem Draft(string? name=null,string notes="")=>new(){Name=string.IsNullOrWhiteSpace(name)?(Channel.Length>0?"Channel "+Channel:Role):name,FrequencyHz=Hz,Mode="NFM",BandwidthHz=12500,Protocols=Protocol,SiteScope=Scope,ChannelLastSeen=Seen,ChannelRoles=Role,ChannelIds=Channel,UplinkHz=Uplink,Signaling=Identifiers,EvidenceStatus=Evidence,Tags="Site channel discovery",Notes=notes+"\n"+Role+"; "+Evidence+"; last observed "+Seen?.ToString("O")};
}
public sealed partial class FrequencyLibrary
{
 internal (int Added,int Updated) SaveSiteChannels(IEnumerable<SiteChannelData> data){var next=items.ToList();int added=0,updated=0;foreach(var c in data){if(c.Hz<=0||c.Hz>6000000000)continue;Guid? parent=null;foreach(string name in c.Folders){var folder=next.FirstOrDefault(i=>i.IsFolder&&i.ParentId==parent&&i.Name.Equals(name,StringComparison.OrdinalIgnoreCase));if(folder==null){folder=new(){IsFolder=true,ParentId=parent,Name=name};next.Add(folder);}parent=folder.Id;}
 var old=next.FirstOrDefault(i=>!i.IsFolder&&i.SiteScope==c.Scope&&i.FrequencyHz==c.Hz)??next.FirstOrDefault(i=>!i.IsFolder&&i.ParentId==parent&&i.FrequencyHz==c.Hz);if(old==null){next.Add(c.Draft() with{ParentId=parent});added++;}else{string channels=string.Join(", ",old.ChannelIds.Split(", ",StringSplitOptions.RemoveEmptyEntries).Append(c.Channel).Where(s=>s.Length>0).Distinct().Take(64));var newer=old with{SiteScope=c.Scope,ChannelLastSeen=c.Seen>old.ChannelLastSeen||old.ChannelLastSeen==null?c.Seen:old.ChannelLastSeen,ChannelRoles=string.Join("; ",old.ChannelRoles.Split("; ",StringSplitOptions.RemoveEmptyEntries).Append(c.Role).Distinct().Take(32)),ChannelIds=channels,UplinkHz=c.Uplink??old.UplinkHz,Signaling=c.Identifiers,EvidenceStatus=c.Evidence,Protocols=old.Protocols is "" or "Unknown"?c.Protocol:old.Protocols};if(newer!=old){next[next.IndexOf(old)]=newer;updated++;}}}
 if(added+updated>0)Commit(next,false);return(added,updated);}
}
